public class StrBuilder_indexOf_TriageGen0Test {

















    @Test
    public void testIndexOf_PartialMatchThenFail() {
        StrBuilder sb = new StrBuilder("ababc");
        // Tests the 'continue outer' logic
        // Try to find "abc" starting at 0. 
        // i=0: "aba" != "abc" -> continue outer
        // i=1: "bab" != "abc" -> continue outer
        // i=2: "abc" == "abc" -> return 2
        Assert.assertEquals(2, sb.indexOf("abc", 0));

        // Try to find "abd"
        Assert.assertEquals(-1, sb.indexOf("abd", 0));
    }


}

